import { useMemo } from 'react'
import type { ComponentProps, ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { getRouteApi } from '@tanstack/react-router'
import { useGetDashboard } from '@bk-dash/client-typescript/typescript'
import type { GetDashboard200 } from '@bk-dash/client-typescript/typescript'

import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { GradientIconBadge } from '@/components/ui/gradient-icon-badge'
import { BalanceIcon, CardIcon, CashIcon, LockIcon, OrderBlockIcon, ReturnIcon, ToolIcon } from '@/components/ui/icons'
import type { IconComponent } from '@/components/ui/icons'
import { enumLabel } from '@/lib/enums'
import { formatCurrency, formatMoneyValue, sumMoney, type MoneyValue } from '@/lib/format'
import { cn } from '@/lib/utils'
import { useTenancyStore } from '@/stores'

import { DiscountCostsToggle } from './DiscountCostsToggle'
import { AdditionalCostRow } from './AdditionalCostRow'
import { CostTooltipLines, OperationalTooltip, type CostTooltipLine } from './CostTooltips'

const routeApi = getRouteApi('/(app)/dashboard/')

type AdditionalCost = GetDashboard200['additionalCost']

// Rows summed into the header total + rendered in order. Typed off the additionalCost schema so the
// row set AND the loading skeleton stay in sync. (draftOrders is national-only + informational, so
// it's appended separately and excluded from the total.)
const COST_KEYS = ['chargeback', 'refund', 'taxes', 'operational', 'warranty'] as const satisfies readonly (keyof AdditionalCost)[]

const DEFAULT_CURRENCY = 'BRL'

interface CostRowView {
	key: string
	icon: IconComponent
	label: string
	value: string
	tooltip: ReactNode
}

/**
 * Additional Costs card — the period's cost categories read from `GetDashboard`'s `additionalCost`
 * top-level, each row revealing its sub-breakdown on hover (operational uses a custom titled
 * tooltip). Owns the dashboard query, feeds rows by props. Works in mono (single-store) and
 * consolidated (multi-store) tenancy via `MoneyValue`. `draftOrders` shows only in *_NATIONAL.
 * All copy is i18n-driven; currency formatting follows the active locale.
 */
export function AdditionalCostsSection({ className, ...props }: ComponentProps<'div'>) {
	const { t, i18n } = useTranslation()
	const locale = i18n.language?.startsWith('en') ? 'en-US' : 'pt-BR'
	const { startDate, endDate, productIds } = routeApi.useSearch()
	const tenancyScope = useTenancyStore(s => s.tenancyScope)
	const { data, isPending, isError } = useGetDashboard({ tenancyScope, startDate, endDate, productIds })

	const view = useMemo(() => {
		if (!data) return null

		const currency = data.kind === 'SINGLE_GLOBAL' || data.kind === 'SINGLE_NATIONAL' ? data.store.currency : DEFAULT_CURRENCY
		const money = (value: MoneyValue) => formatMoneyValue(value, currency, locale)
		const lines = (items: CostTooltipLine[]): ReactNode => <CostTooltipLines lines={items} />
		const ac = data.additionalCost

		const byKey: Record<(typeof COST_KEYS)[number], { icon: IconComponent; label: string; total: MoneyValue; tooltip: ReactNode }> = {
			chargeback: {
				icon: CardIcon,
				label: t('dashboard.additionalCosts.rows.chargeback'),
				total: ac.chargeback.byStatus.total.value,
				tooltip: lines([
					{ label: t('dashboard.additionalCosts.tooltip.open'), value: money(ac.chargeback.byStatus.segments.OPEN.value) },
					{ label: t('dashboard.additionalCosts.tooltip.lost'), value: money(ac.chargeback.byStatus.segments.LOST.value) },
					{ label: t('dashboard.additionalCosts.tooltip.won'), value: money(ac.chargeback.byStatus.segments.WON.value) },
					{ label: t('dashboard.additionalCosts.tooltip.fees'), value: money(ac.chargeback.fees.value) },
				]),
			},
			refund: {
				icon: ReturnIcon,
				label: t('dashboard.additionalCosts.rows.refund'),
				total: ac.refund.value,
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.total'), value: money(ac.refund.value) }]),
			},
			taxes: {
				icon: BalanceIcon,
				label: t('dashboard.additionalCosts.rows.taxes'),
				total: sumMoney([ac.taxes.ads.value, ac.taxes.others.value]),
				tooltip: lines([
					{ label: t('dashboard.additionalCosts.tooltip.ads'), value: money(ac.taxes.ads.value) },
					{ label: t('dashboard.additionalCosts.tooltip.others'), value: money(ac.taxes.others.value) },
				]),
			},
			operational: {
				icon: ToolIcon,
				label: t('dashboard.additionalCosts.rows.operational'),
				total: ac.operational.total.value,
				tooltip: (
					<OperationalTooltip
						title={t('dashboard.additionalCosts.tooltip.operationalTitle')}
						items={
							ac.operational.items.length
								? ac.operational.items.map(item => ({
										label: `${item.name} (${enumLabel('OperationalCostRecurrency', item.frequency)})`,
										value: formatCurrency(item.amount, item.currency, locale),
									}))
								: [{ label: t('dashboard.additionalCosts.tooltip.noCosts'), value: money(0) }]
						}
					/>
				),
			},
			warranty: {
				icon: LockIcon,
				label: t('dashboard.additionalCosts.rows.warranty'),
				total: ac.warranty.value,
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.total'), value: money(ac.warranty.value) }]),
			},
		}

		const rows: CostRowView[] = COST_KEYS.map(key => {
			const r = byKey[key]
			return { key, icon: r.icon, label: r.label, value: money(r.total), tooltip: r.tooltip }
		})

		// draftOrders — national only (the discriminated union carries it on the *_NATIONAL variants);
		// informational (count + value of draft orders), not summed into the total.
		if (data.kind === 'SINGLE_NATIONAL' || data.kind === 'MULTI_NATIONAL') {
			const draftOrders = data.additionalCost.draftOrders
			rows.push({
				key: 'draftOrders',
				icon: OrderBlockIcon,
				label: t('dashboard.additionalCosts.rows.draftOrders'),
				value: money(draftOrders.value.value),
				tooltip: lines([{ label: t('dashboard.additionalCosts.tooltip.count'), value: String(draftOrders.count.value) }]),
			})
		}

		const headerTotal = money(sumMoney(COST_KEYS.map(key => byKey[key].total)))
		return { headerTotal, rows }
	}, [data, t, locale])

	return (
		<Card className={cn('gap-4 p-6', className)} {...props}>
			<div className="flex items-center gap-4">
				<GradientIconBadge icon={CashIcon} />
				<div className="flex min-w-0 flex-col gap-2">
					<span className="text-muted-foreground text-lg font-medium">{t('dashboard.additionalCosts.title')}</span>
					{isPending ? (
						<Skeleton className="mt-1 h-8 w-32" />
					) : (
						<span className="truncate text-3xl font-bold text-foreground">{view ? view.headerTotal : '—'}</span>
					)}
				</div>
			</div>

			<DiscountCostsToggle className="mx-2" />

			<div className="border-t border-border/60" />

			<div className="flex flex-col gap-3" role="list" aria-label={t('dashboard.additionalCosts.listAria')}>
				{isPending ? (
					COST_KEYS.map(key => <Skeleton key={key} className="h-5 w-full" />)
				) : isError || !view ? (
					<p className="text-sm text-muted-foreground">{t('dashboard.additionalCosts.loadError')}</p>
				) : (
					view.rows.map(row => (
						<AdditionalCostRow key={row.key} icon={row.icon} label={row.label} value={row.value} tooltip={row.tooltip} />
					))
				)}
			</div>
		</Card>
	)
}

